--feature

--aerial_refuelling.aerialrefuelling_view

drop materialized view if exists aerial_refuelling.aerialrefuelling_view cascade;
create materialized view aerial_refuelling.aerialrefuelling_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeAerialRefuellingPrefixType for getdesignatorprefixitem,
    aerial_refuelling.aerialrefuelling_t.designatorprefix::text,
    aerial_refuelling.aerialrefuelling_t.designatorprefixnilreason::text,
    -- embedded NoNumberType for getdesignatornumberitem,
    aerial_refuelling.aerialrefuelling_t.designatornumber::text,
    aerial_refuelling.aerialrefuelling_t.designatornumbernilreason::text,
    -- embedded TextDesignatorType for getdesignatorsuffixitem,
    aerial_refuelling.aerialrefuelling_t.designatorsuffix::text,
    aerial_refuelling.aerialrefuelling_t.designatorsuffixnilreason::text,
    -- embedded CodeCardinalDirectionType for getdesignatordirectionitem,
    aerial_refuelling.aerialrefuelling_t.designatordirection::text,
    aerial_refuelling.aerialrefuelling_t.designatordirectionnilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    aerial_refuelling.aerialrefuelling_t.name::text,
    aerial_refuelling.aerialrefuelling_t.namenilreason::text,
    -- embedded CodeAerialRefuellingType for gettypeitem,
    aerial_refuelling.aerialrefuelling_t.type::text,
    aerial_refuelling.aerialrefuelling_t.typenilreason::text,
    -- embedded NoNumberType for getradarbeaconsettingitem,
    aerial_refuelling.aerialrefuelling_t.radarbeaconsetting::text,
    aerial_refuelling.aerialrefuelling_t.radarbeaconsettingnilreason::text,
    -- embedded NoNumberType for getxbandradarsettingitem,
    aerial_refuelling.aerialrefuelling_t.xbandradarsetting::text,
    aerial_refuelling.aerialrefuelling_t.xbandradarsettingnilreason::text,
    -- embedded CodeTACANChannelType for gettankerchannelitem,
    aerial_refuelling.aerialrefuelling_t.tankerchannel::text,
    aerial_refuelling.aerialrefuelling_t.tankerchannelnilreason::text,
    -- embedded CodeTACANChannelType for getreceiverchannelitem,
    aerial_refuelling.aerialrefuelling_t.receiverchannel::text,
    aerial_refuelling.aerialrefuelling_t.receiverchannelnilreason::text,
    -- embedded CodeYesNoType for gethelicopterrouteitem,
    aerial_refuelling.aerialrefuelling_t.helicopterroute::text,
    aerial_refuelling.aerialrefuelling_t.helicopterroutenilreason::text,
    -- embedded CodeYesNoType for getspecialrefuellingitem,
    aerial_refuelling.aerialrefuelling_t.specialrefuelling::text,
    aerial_refuelling.aerialrefuelling_t.specialrefuellingnilreason::text,
    -- embedded CodeYesNoType for getbidirectionaluseitem,
    aerial_refuelling.aerialrefuelling_t.bidirectionaluse::text,
    aerial_refuelling.aerialrefuelling_t.bidirectionalusenilreason::text,
    -- embedded CodeDirectionTurnType for getreversedirectionturnitem,
    aerial_refuelling.aerialrefuelling_t.reversedirectionturn::text,
    aerial_refuelling.aerialrefuelling_t.reversedirectionturnnilreason::text,
    -- composed AerialRefuellingPropertyType for opposite_track,
    jsonb_build_object('href', aerialrefuelling_wnyhag.href,
    'nilreason', aerialrefuelling_wnyhag.nil_reason,
    'title', aerialrefuelling_wnyhag.simple_link_title) AS opposite_track,
    -- composed RouteAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_avlblt_link join aixm.aixm_property on aerial_refuelling.arlrfllngtmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_avlblt_link.aerialrefuelling_t_hjid ) as availability,
    -- composed AirspacePropertyType for protecting_airspace,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airspace.airspace_p.href,
    'nilreason', airspace.airspace_p.nil_reason,
    'title', airspace.airspace_p.simple_link_title)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_prtctngarspc_link join airspace.airspace_p on aerial_refuelling.arlrfllngtmslctp_prtctngarspc_link.protectingairspace_hjid = airspace.airspace_p.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_prtctngarspc_link.aerialrefuelling_t_hjid ) as protecting_airspace,
    -- composed AerialRefuellingTrackPropertyType for track,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_trck_link join aixm.aixm_property on aerial_refuelling.arlrfllngtmslctp_trck_link.track_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_trck_link.aerialrefuelling_t_hjid ) as track,
    -- composed AerialRefuellingAnchorPropertyType for anchor,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_anchr_link join aixm.aixm_property on aerial_refuelling.arlrfllngtmslctp_anchr_link.anchor_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_anchr_link.aerialrefuelling_t_hjid ) as anchor,
    -- composed AuthorityForAerialRefuellingPropertyType for managing_organisation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_mngngorgnstn_link join aixm.aixm_property on aerial_refuelling.arlrfllngtmslctp_mngngorgnstn_link.managingorganisation_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_mngngorgnstn_link.aerialrefuelling_t_hjid ) as managing_organisation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngtmslctp_annttn_link join aixm.aixm_property on aerial_refuelling.arlrfllngtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling.arlrfllngtmslctp_annttn_link.aerialrefuelling_t_hjid ) as annotation
from aixm.aixm_feature
inner join aerial_refuelling.aerialrefuelling_f on aixm.aixm_feature.hjid = aerial_refuelling.aerialrefuelling_f.hjid
inner join aerial_refuelling.aerialrefuelling_tp on aixm.aixm_feature.hjid = aerial_refuelling.aerialrefuelling_tp.timeslice_hjid
inner join aerial_refuelling.aerialrefuelling_t on aerial_refuelling.aerialrefuelling_tp.aerialrefuellingtimeslice_hjid = aerial_refuelling.aerialrefuelling_t.hjid
inner join aixm.aixm_timeslice on aerial_refuelling.aerialrefuelling_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AerialRefuellingPropertyType for opposite_track
left join aerial_refuelling.arlrfllngtmslctp_oppsttrck_link aerial_refuelling_rhbmrq on aerial_refuelling.aerialrefuelling_t.hjid = aerial_refuelling_rhbmrq.aerialrefuelling_t_hjid
left join aerial_refuelling.aerialrefuelling_p aerialrefuelling_wnyhag on aerial_refuelling_rhbmrq.oppositetrack_hjid = aerialrefuelling_wnyhag.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists aerial_refuelling_aerialrefuelling_hjid on aerial_refuelling.aerialrefuelling_view (message_hjid, hjid, timeslice_hjid);
create index if not exists aerial_refuelling_aerialrefuelling_hjid on aerial_refuelling.aerialrefuelling_view (hjid);

--navaids_point.aeronauticalgroundlight_view

drop materialized view if exists navaids_point.aeronauticalgroundlight_view cascade;
create materialized view navaids_point.aeronauticalgroundlight_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded TextNameType for getaixmnameitem,
    navaids_point.aeronauticalgroundlight_t.name::text,
    navaids_point.aeronauticalgroundlight_t.namenilreason::text,
    -- embedded CodeGroundLightingType for gettypeitem,
    navaids_point.aeronauticalgroundlight_t.type::text,
    navaids_point.aeronauticalgroundlight_t.typenilreason::text,
    -- embedded CodeColourType for getcolouritem,
    navaids_point.aeronauticalgroundlight_t.colour::text,
    navaids_point.aeronauticalgroundlight_t.colournilreason::text,
    -- embedded CodeYesNoType for getflashingitem,
    navaids_point.aeronauticalgroundlight_t.flashing::text,
    navaids_point.aeronauticalgroundlight_t.flashingnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_ourirt.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_ourirt.hjid,
    'id', aixm_elevated_point_pt_view_ourirt.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_ourirt.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_ourirt.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_ourirt.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_ourirt.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_ourirt.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_ourirt.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_ourirt.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_ourirt.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_ourirt.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_ourirt.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_ourirt.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_ourirt.elevation_nilreason) AS location,
    -- composed VerticalStructurePropertyType for structure_beacon,
    jsonb_build_object('href', verticalstructure_uwpznq.href,
    'nilreason', verticalstructure_uwpznq.nil_reason,
    'title', verticalstructure_uwpznq.simple_link_title) AS structure_beacon,
    -- composed AirportHeliportPropertyType for aerodrome_beacon,
    jsonb_build_object('href', airportheliport_xhcciv.href,
    'nilreason', airportheliport_xhcciv.nil_reason,
    'title', airportheliport_xhcciv.simple_link_title) AS aerodrome_beacon,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.arntclgrndlghttmslctp_annttn_link join aixm.aixm_property on navaids_point.arntclgrndlghttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.aeronauticalgroundlight_t.hjid = navaids_point.arntclgrndlghttmslctp_annttn_link.aeronauticalgroundlight_t_hjid ) as annotation
from aixm.aixm_feature
inner join navaids_point.aeronauticalgroundlight_f on aixm.aixm_feature.hjid = navaids_point.aeronauticalgroundlight_f.hjid
inner join navaids_point.aeronauticalgroundlight_tp on aixm.aixm_feature.hjid = navaids_point.aeronauticalgroundlight_tp.timeslice_hjid
inner join navaids_point.aeronauticalgroundlight_t on navaids_point.aeronauticalgroundlight_tp.aeronauticalgroundlighttimeslice_hjid = navaids_point.aeronauticalgroundlight_t.hjid
inner join aixm.aixm_timeslice on navaids_point.aeronauticalgroundlight_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed VerticalStructurePropertyType for structure_beacon
left join navaids_point.arntclgrndlghttmslctp_strctrbcn_link navaids_point_vuxbxr on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_vuxbxr.aeronauticalgroundlight_t_hjid
left join obstacle.verticalstructure_p verticalstructure_uwpznq on navaids_point_vuxbxr.structurebeacon_hjid = verticalstructure_uwpznq.hjid
-- composed AirportHeliportPropertyType for aerodrome_beacon
left join navaids_point.arntclgrndlghttmslctp_ardrmbcn_link navaids_point_sdcfkl on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_sdcfkl.aeronauticalgroundlight_t_hjid
left join airport_heliport.airportheliport_p airportheliport_xhcciv on navaids_point_sdcfkl.aerodromebeacon_hjid = airportheliport_xhcciv.hjid
-- composed AIXMElevatedPointPropertyType for location
left join navaids_point.arntclgrndlghttmslctp_lctn_link navaids_point_ngwbpi on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_ngwbpi.aeronauticalgroundlight_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_ourirt on navaids_point_ngwbpi.location_hjid = aixm_elevated_point_pt_view_ourirt.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists navaids_point_aeronauticalgroundlight_hjid on navaids_point.aeronauticalgroundlight_view (message_hjid, hjid, timeslice_hjid);
create index if not exists navaids_point_aeronauticalgroundlight_hjid on navaids_point.aeronauticalgroundlight_view (hjid);
create index if not exists navaids_point_aeronauticalgroundlight_location_geom on navaids_point.aeronauticalgroundlight_view  using gist (location_geom);

--service.aircraftgroundservice_view

