    jsonb_build_object('hjid', aixm_elevated_point_pt_view_jpeisi.hjid,
    'id', aixm_elevated_point_pt_view_jpeisi.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_jpeisi.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_jpeisi.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_jpeisi.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_jpeisi.geoidundulation,
