    'verticalaccuracy', aixm_elevated_point_pt_view_jpeisi.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_jpeisi.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_jpeisi.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_jpeisi.elevation,
