    -- composed RadioCommunicationChannelPropertyType for radio_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('href', service.radiocommunicationchannel_p.href,
    'nilreason', service.radiocommunicationchannel_p.nil_reason,
    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.arcrftgrndsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.arcrftgrndsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.aircraftgroundservice_t.hjid = service.arcrftgrndsrvctmslctp_rdcmmnctn_link.aircraftgroundservice_t_hjid ) as radio_communication,
    -- composed ContactInformationPropertyType for ground_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.arcrftgrndsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.arcrftgrndsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.aircraftgroundservice_t.hjid = service.arcrftgrndsrvctmslctp_grndcmmnctn_link.aircraftgroundservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
