select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded TextDesignatorType for getdesignatoritem,
    airport_heliport.airporthotspot_t.designator::text,
    airport_heliport.airporthotspot_t.designatornilreason::text,
    -- embedded TextInstructionType for getinstructionitem,
    airport_heliport.airporthotspot_t.instruction::text,
    airport_heliport.airporthotspot_t.instructionnilreason::text,
    -- composed geometry AIXMElevatedSurfacePropertyType for area,
    aixm_elevated_surface_pt_view_rdnnqk.geom as area_geom,
    jsonb_build_object('hjid', aixm_elevated_surface_pt_view_rdnnqk.hjid,
    'id', aixm_elevated_surface_pt_view_rdnnqk.id,
    'horizontalaccuracy', aixm_elevated_surface_pt_view_rdnnqk.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_surface_pt_view_rdnnqk.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_surface_pt_view_rdnnqk.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_surface_pt_view_rdnnqk.geoidundulation,
    'geoidundulation_uom', aixm_elevated_surface_pt_view_rdnnqk.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_surface_pt_view_rdnnqk.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_surface_pt_view_rdnnqk.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_surface_pt_view_rdnnqk.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_surface_pt_view_rdnnqk.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_surface_pt_view_rdnnqk.elevation,
    'elevation_uom', aixm_elevated_surface_pt_view_rdnnqk.elevation_uom,
    'elevation_nilreason', aixm_elevated_surface_pt_view_rdnnqk.elevation_nilreason) AS area,
    -- composed AirportHeliportPropertyType for affected_airport,
    jsonb_build_object('href', airportheliport_oaoxil.href,
    'nilreason', airportheliport_oaoxil.nil_reason,
    'title', airportheliport_oaoxil.simple_link_title) AS affected_airport,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.arprthtspttmslctp_annttn_link join aixm.aixm_property on airport_heliport.arprthtspttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.airporthotspot_t.hjid = airport_heliport.arprthtspttmslctp_annttn_link.airporthotspot_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.airporthotspot_f on aixm.aixm_feature.hjid = airport_heliport.airporthotspot_f.hjid
inner join airport_heliport.airporthotspot_tp on aixm.aixm_feature.hjid = airport_heliport.airporthotspot_tp.timeslice_hjid
inner join airport_heliport.airporthotspot_t on airport_heliport.airporthotspot_tp.airporthotspottimeslice_hjid = airport_heliport.airporthotspot_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.airporthotspot_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedSurfacePropertyType for area
left join airport_heliport.arprthtspttmslctp_ar_link airport_heliport_hqefep on airport_heliport.airporthotspot_t.hjid = airport_heliport_hqefep.airporthotspot_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_rdnnqk on airport_heliport_hqefep.area_hjid = aixm_elevated_surface_pt_view_rdnnqk.hjid
-- composed AirportHeliportPropertyType for affected_airport
left join airport_heliport.arprthtspttmslctp_affctdarprt_link airport_heliport_lixygl on airport_heliport.airporthotspot_t.hjid = airport_heliport_lixygl.airporthotspot_t_hjid
left join airport_heliport.airportheliport_p airportheliport_oaoxil on airport_heliport_lixygl.affectedairport_hjid = airportheliport_oaoxil.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists airport_heliport_airporthotspot_hjid on airport_heliport.airporthotspot_view (message_hjid, hjid, timeslice_hjid);
create index if not exists airport_heliport_airporthotspot_hjid on airport_heliport.airporthotspot_view (hjid);
create index if not exists airport_heliport_airporthotspot_area_geom on airport_heliport.airporthotspot_view  using gist (area_geom);

