    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.arprtspplssrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.arprtspplssrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.airportsuppliesservice_t.hjid = service.arprtspplssrvctmslctp_rdcmmnctn_link.airportsuppliesservice_t_hjid ) as radio_communication,
