    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.arspcbrdrcrssngtmslctp_annttn_link join aixm.aixm_property on route.arspcbrdrcrssngtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.airspacebordercrossing_t.hjid = route.arspcbrdrcrssngtmslctp_annttn_link.airspacebordercrossing_t_hjid ) as annotation
