    navaids_point.azimuth_t.truebearing::text,
    navaids_point.azimuth_t.truebearingnilreason::text,
    -- embedded ValAngleType for gettruebearingaccuracyitem,
    navaids_point.azimuth_t.truebearingaccuracy::text,
    navaids_point.azimuth_t.truebearingaccuracynilreason::text,
    -- embedded ValBearingType for getmagneticbearingitem,
    navaids_point.azimuth_t.magneticbearing::text,
    navaids_point.azimuth_t.magneticbearingnilreason::text,
    -- embedded ValAngleType for getangleproportionalleftitem,
    navaids_point.azimuth_t.angleproportionalleft::text,
