    navaids_point.azimuth_t.anglecoverrightnilreason::text,
    -- embedded CodeMLSChannelType for getchannelitem,
    navaids_point.azimuth_t.channel::text,
    navaids_point.azimuth_t.channelnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_ylcnqm.geom as location_geom,
