    'geoidundulation_uom', aixm_elevated_point_pt_view_ylcnqm.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_ylcnqm.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_ylcnqm.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_ylcnqm.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_ylcnqm.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_ylcnqm.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_ylcnqm.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_ylcnqm.elevation_nilreason) AS location,
    -- composed AuthorityForNavaidEquipmentPropertyType for authority,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.azmthtmslctp_athrt_link join aixm.aixm_property on navaids_point.azmthtmslctp_athrt_link.authority_hjid = aixm.aixm_property.hjid where navaids_point.azimuth_t.hjid = navaids_point.azmthtmslctp_athrt_link.azimuth_t_hjid ) as authority,
    -- composed NavaidEquipmentMonitoringPropertyType for monitoring,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.azmthtmslctp_mntrng_link join aixm.aixm_property on navaids_point.azmthtmslctp_mntrng_link.monitoring_hjid = aixm.aixm_property.hjid where navaids_point.azimuth_t.hjid = navaids_point.azmthtmslctp_mntrng_link.azimuth_t_hjid ) as monitoring,
    -- composed NavaidOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.azmthtmslctp_avlblt_link join aixm.aixm_property on navaids_point.azmthtmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where navaids_point.azimuth_t.hjid = navaids_point.azmthtmslctp_avlblt_link.azimuth_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.azmthtmslctp_annttn_link join aixm.aixm_property on navaids_point.azmthtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.azimuth_t.hjid = navaids_point.azmthtmslctp_annttn_link.azimuth_t_hjid ) as annotation
from aixm.aixm_feature
inner join navaids_point.azimuth_f on aixm.aixm_feature.hjid = navaids_point.azimuth_f.hjid
inner join navaids_point.azimuth_tp on aixm.aixm_feature.hjid = navaids_point.azimuth_tp.timeslice_hjid
inner join navaids_point.azimuth_t on navaids_point.azimuth_tp.azimuthtimeslice_hjid = navaids_point.azimuth_t.hjid
inner join aixm.aixm_timeslice on navaids_point.azimuth_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join navaids_point.azmthtmslctp_lctn_link navaids_point_ewiztr on navaids_point.azimuth_t.hjid = navaids_point_ewiztr.azimuth_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_ylcnqm on navaids_point_ewiztr.location_hjid = aixm_elevated_point_pt_view_ylcnqm.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists navaids_point_azimuth_hjid on navaids_point.azimuth_view (message_hjid, hjid, timeslice_hjid);
create index if not exists navaids_point_azimuth_hjid on navaids_point.azimuth_view (hjid);
create index if not exists navaids_point_azimuth_location_geom on navaids_point.azimuth_view  using gist (location_geom);

