    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeVerticalReferenceType for getupperlimitreferenceitem,
    shared.holdingassessment_t.upperlimitreference::text,
    shared.holdingassessment_t.upperlimitreferencenilreason::text,
    -- embedded CodeVerticalReferenceType for getlowerlimitreferenceitem,
    shared.holdingassessment_t.lowerlimitreference::text,
    shared.holdingassessment_t.lowerlimitreferencenilreason::text,
    -- embedded TextNameType for getpatterntemplateitem,
    shared.holdingassessment_t.patterntemplate::text,
    shared.holdingassessment_t.patterntemplatenilreason::text,
    -- embedded CodeYesNoType for getturbulentairitem,
    shared.holdingassessment_t.turbulentair::text,
    shared.holdingassessment_t.turbulentairnilreason::text,
    -- embedded ValDistanceVerticalType for getupperlimititem,
    shared.holdingassessment_t.upperlimit::text,
    shared.holdingassessment_t.upperlimituom::text,
    shared.holdingassessment_t.upperlimitnilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlimititem,
    shared.holdingassessment_t.lowerlimit::text,
    shared.holdingassessment_t.lowerlimituom::text,
    shared.holdingassessment_t.lowerlimitnilreason::text,
    -- embedded ValSpeedType for getspeedlimititem,
    shared.holdingassessment_t.speedlimit::text,
    shared.holdingassessment_t.speedlimituom::text,
    shared.holdingassessment_t.speedlimitnilreason::text,
    -- embedded ValDistanceType for getleglengthtowarditem,
    shared.holdingassessment_t.leglengthtoward::text,
    shared.holdingassessment_t.leglengthtowarduom::text,
    shared.holdingassessment_t.leglengthtowardnilreason::text,
    -- embedded ValDistanceType for getleglengthawayitem,
    shared.holdingassessment_t.leglengthaway::text,
    shared.holdingassessment_t.leglengthawayuom::text,
    shared.holdingassessment_t.leglengthawaynilreason::text,
    -- composed SegmentPointPropertyType for holding_point,
    jsonb_build_object('hjid', aixm_property_drlrdi.hjid,
    'nilreason', aixm_property_drlrdi.nil_reason) AS holding_point,
    -- composed UnplannedHoldingPropertyType for unplanned_holding,
    jsonb_build_object('href', unplannedholding_lrzceo.href,
    'nilreason', unplannedholding_lrzceo.nil_reason,
    'title', unplannedholding_lrzceo.simple_link_title) AS unplanned_holding,
    -- composed HoldingPatternPropertyType for assessed_holding_pattern,
    jsonb_build_object('href', holdingpattern_ovpmmb.href,
    'nilreason', holdingpattern_ovpmmb.nil_reason,
    'title', holdingpattern_ovpmmb.simple_link_title) AS assessed_holding_pattern,
    -- composed ObstacleAssessmentAreaPropertyType for obstacle_assessment,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.hldngassssmnttmslctp_obstclassssmnt_link join aixm.aixm_property on shared.hldngassssmnttmslctp_obstclassssmnt_link.obstacleassessment_hjid = aixm.aixm_property.hjid where shared.holdingassessment_t.hjid = shared.hldngassssmnttmslctp_obstclassssmnt_link.holdingassessment_t_hjid ) as obstacle_assessment,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.hldngassssmnttmslctp_annttn_link join aixm.aixm_property on shared.hldngassssmnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where shared.holdingassessment_t.hjid = shared.hldngassssmnttmslctp_annttn_link.holdingassessment_t_hjid ) as annotation
from aixm.aixm_feature
inner join shared.holdingassessment_f on aixm.aixm_feature.hjid = shared.holdingassessment_f.hjid
inner join shared.holdingassessment_tp on aixm.aixm_feature.hjid = shared.holdingassessment_tp.timeslice_hjid
inner join shared.holdingassessment_t on shared.holdingassessment_tp.holdingassessmenttimeslice_hjid = shared.holdingassessment_t.hjid
inner join aixm.aixm_timeslice on shared.holdingassessment_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed SegmentPointPropertyType for holding_point
left join shared.hldngassssmnttmslctp_hldngpnt_link shared_hfyojx on shared.holdingassessment_t.hjid = shared_hfyojx.holdingassessment_t_hjid
left join aixm.aixm_property aixm_property_drlrdi on shared_hfyojx.holdingpoint_hjid = aixm_property_drlrdi.hjid
-- composed UnplannedHoldingPropertyType for unplanned_holding
left join shared.hldngassssmnttmslctp_unplnndhldng_link shared_veerjf on shared.holdingassessment_t.hjid = shared_veerjf.holdingassessment_t_hjid
left join holding.unplannedholding_p unplannedholding_lrzceo on shared_veerjf.unplannedholding_hjid = unplannedholding_lrzceo.hjid
-- composed HoldingPatternPropertyType for assessed_holding_pattern
left join shared.hldngassssmnttmslctp_assssdhldngpttrn_link shared_ruqmse on shared.holdingassessment_t.hjid = shared_ruqmse.holdingassessment_t_hjid
left join holding.holdingpattern_p holdingpattern_ovpmmb on shared_ruqmse.assessedholdingpattern_hjid = holdingpattern_ovpmmb.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists shared_holdingassessment_hjid on shared.holdingassessment_view (message_hjid, hjid, timeslice_hjid);
create index if not exists shared_holdingassessment_hjid on shared.holdingassessment_view (hjid);

--holding.holdingpattern_view

