    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeHoldingUsageType for gettypeitem,
    holding.holdingpattern_t.type::text,
    holding.holdingpattern_t.typenilreason::text,
    -- embedded ValBearingType for getoutboundcourseitem,
    holding.holdingpattern_t.outboundcourse::text,
    holding.holdingpattern_t.outboundcoursenilreason::text,
    -- embedded CodeCourseType for getoutboundcoursetypeitem,
    holding.holdingpattern_t.outboundcoursetype::text,
    holding.holdingpattern_t.outboundcoursetypenilreason::text,
    -- embedded ValBearingType for getinboundcourseitem,
    holding.holdingpattern_t.inboundcourse::text,
    holding.holdingpattern_t.inboundcoursenilreason::text,
    -- embedded CodeDirectionTurnType for getturndirectionitem,
    holding.holdingpattern_t.turndirection::text,
    holding.holdingpattern_t.turndirectionnilreason::text,
    -- embedded CodeVerticalReferenceType for getupperlimitreferenceitem,
    holding.holdingpattern_t.upperlimitreference::text,
    holding.holdingpattern_t.upperlimitreferencenilreason::text,
    -- embedded CodeVerticalReferenceType for getlowerlimitreferenceitem,
    holding.holdingpattern_t.lowerlimitreference::text,
    holding.holdingpattern_t.lowerlimitreferencenilreason::text,
    -- embedded TextInstructionType for getinstructionitem,
    holding.holdingpattern_t.instruction::text,
    holding.holdingpattern_t.instructionnilreason::text,
    -- embedded CodeYesNoType for getnonstandardholdingitem,
    holding.holdingpattern_t.nonstandardholding::text,
    holding.holdingpattern_t.nonstandardholdingnilreason::text,
    -- embedded ValDistanceVerticalType for getupperlimititem,
    holding.holdingpattern_t.upperlimit::text,
    holding.holdingpattern_t.upperlimituom::text,
    holding.holdingpattern_t.upperlimitnilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlimititem,
    holding.holdingpattern_t.lowerlimit::text,
    holding.holdingpattern_t.lowerlimituom::text,
    holding.holdingpattern_t.lowerlimitnilreason::text,
    -- embedded ValSpeedType for getspeedlimititem,
    holding.holdingpattern_t.speedlimit::text,
    holding.holdingpattern_t.speedlimituom::text,
    holding.holdingpattern_t.speedlimitnilreason::text,
    -- composed geometry AIXMCurvePropertyType for extent,
    aixm_curve_pt_view_xcczse.geom as extent_geom,
    jsonb_build_object('hjid', aixm_curve_pt_view_xcczse.hjid,
    'id', aixm_curve_pt_view_xcczse.id,
    'horizontalaccuracy', aixm_curve_pt_view_xcczse.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_curve_pt_view_xcczse.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_curve_pt_view_xcczse.horizontalaccuracy_nilreason) AS extent,
    -- composed SegmentPointPropertyType for outbound_leg_span_end_point,
    jsonb_build_object('hjid', aixm_property_ktmkfo.hjid,
    'nilreason', aixm_property_ktmkfo.nil_reason) AS outbound_leg_span_end_point,
    -- composed HoldingPatternDistancePropertyType for outbound_leg_span_end_distance,
    jsonb_build_object('hjid', aixm_property_hcujda.hjid,
    'nilreason', aixm_property_hcujda.nil_reason) AS outbound_leg_span_end_distance,
    -- composed HoldingPatternDurationPropertyType for outbound_leg_span_end_time,
    jsonb_build_object('hjid', aixm_property_lwzedl.hjid,
    'nilreason', aixm_property_lwzedl.nil_reason) AS outbound_leg_span_end_time,
    -- composed SegmentPointPropertyType for holding_point,
    jsonb_build_object('hjid', aixm_property_hrqueo.hjid,
    'nilreason', aixm_property_hrqueo.nil_reason) AS holding_point,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from holding.hldngpttrntmslctp_annttn_link join aixm.aixm_property on holding.hldngpttrntmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where holding.holdingpattern_t.hjid = holding.hldngpttrntmslctp_annttn_link.holdingpattern_t_hjid ) as annotation
from aixm.aixm_feature
inner join holding.holdingpattern_f on aixm.aixm_feature.hjid = holding.holdingpattern_f.hjid
inner join holding.holdingpattern_tp on aixm.aixm_feature.hjid = holding.holdingpattern_tp.timeslice_hjid
inner join holding.holdingpattern_t on holding.holdingpattern_tp.holdingpatterntimeslice_hjid = holding.holdingpattern_t.hjid
inner join aixm.aixm_timeslice on holding.holdingpattern_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed SegmentPointPropertyType for outbound_leg_span_end_point
left join holding.hldngpttrntmslctp_otbndlgspnendpnt_link holding_bphxpg on holding.holdingpattern_t.hjid = holding_bphxpg.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_ktmkfo on holding_bphxpg.outboundlegspanendpoint_hjid = aixm_property_ktmkfo.hjid
-- composed HoldingPatternDistancePropertyType for outbound_leg_span_end_distance
left join holding.hldngpttrntmslctp_otbndlgspnenddstnc_link holding_acnbrb on holding.holdingpattern_t.hjid = holding_acnbrb.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_hcujda on holding_acnbrb.outboundlegspanenddistance_hjid = aixm_property_hcujda.hjid
-- composed HoldingPatternDurationPropertyType for outbound_leg_span_end_time
left join holding.hldngpttrntmslctp_otbndlgspnendtm_link holding_siavsy on holding.holdingpattern_t.hjid = holding_siavsy.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_lwzedl on holding_siavsy.outboundlegspanendtime_hjid = aixm_property_lwzedl.hjid
-- composed SegmentPointPropertyType for holding_point
left join holding.hldngpttrntmslctp_hldngpnt_link holding_fardhn on holding.holdingpattern_t.hjid = holding_fardhn.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_hrqueo on holding_fardhn.holdingpoint_hjid = aixm_property_hrqueo.hjid
-- composed AIXMCurvePropertyType for extent
left join holding.hldngpttrntmslctp_extnt_link holding_gppcba on holding.holdingpattern_t.hjid = holding_gppcba.holdingpattern_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_xcczse on holding_gppcba.extent_hjid = aixm_curve_pt_view_xcczse.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists holding_holdingpattern_hjid on holding.holdingpattern_view (message_hjid, hjid, timeslice_hjid);
create index if not exists holding_holdingpattern_hjid on holding.holdingpattern_view (hjid);
create index if not exists holding_holdingpattern_extent_geom on holding.holdingpattern_view  using gist (extent_geom);

--service.informationservice_view

drop materialized view if exists service.informationservice_view cascade;
create materialized view service.informationservice_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
