    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeFlightDestinationType for getflightoperationsitem,
    service.informationservice_t.flightoperations::text,
    service.informationservice_t.flightoperationsnilreason::text,
    -- embedded CodeFacilityRankingType for getrankitem,
    service.informationservice_t.rank::text,
    service.informationservice_t.ranknilreason::text,
    -- embedded CodeYesNoType for getcomplianticaoitem,
    service.informationservice_t.complianticao::text,
    service.informationservice_t.complianticaonilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    service.informationservice_t.name::text,
    service.informationservice_t.namenilreason::text,
    -- embedded CodeServiceInformationType for gettypeitem,
    service.informationservice_t.type::text,
    service.informationservice_t.typenilreason::text,
    -- embedded CodeYesNoType for getvoiceitem,
    service.informationservice_t.voice::text,
    service.informationservice_t.voicenilreason::text,
    -- embedded CodeYesNoType for getdatalinkitem,
    service.informationservice_t.datalink::text,
    service.informationservice_t.datalinknilreason::text,
    -- embedded CodeYesNoType for getrecordeditem,
    service.informationservice_t.recorded::text,
    service.informationservice_t.recordednilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_fbrivt.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_fbrivt.hjid,
    'id', aixm_elevated_point_pt_view_fbrivt.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_fbrivt.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_fbrivt.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_fbrivt.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_fbrivt.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_fbrivt.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_fbrivt.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_fbrivt.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_fbrivt.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_fbrivt.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_fbrivt.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_fbrivt.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_fbrivt.elevation_nilreason) AS location,
    -- composed UnitPropertyType for service_provider,
    jsonb_build_object('href', unit_rxiofu.href,
