    (select coalesce(jsonb_agg(jsonb_build_object('href', service.radiocommunicationchannel_p.href,
    'nilreason', service.radiocommunicationchannel_p.nil_reason,
    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.infrmtnsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.infrmtnsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_rdcmmnctn_link.informationservice_t_hjid ) as radio_communication,
