    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.infrmtnsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.infrmtnsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_grndcmmnctn_link.informationservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.infrmtnsrvctmslctp_avlblt_link join aixm.aixm_property on service.infrmtnsrvctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_avlblt_link.informationservice_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.infrmtnsrvctmslctp_annttn_link join aixm.aixm_property on service.infrmtnsrvctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_annttn_link.informationservice_t_hjid ) as annotation,
    -- composed VORPropertyType for navaid_broadcast,
    (select coalesce(jsonb_agg(jsonb_build_object('href', navaids_point.vor_p.href,
    'nilreason', navaids_point.vor_p.nil_reason,
    'title', navaids_point.vor_p.simple_link_title)),'[]'::jsonb) from service.infrmtnsrvctmslctp_nvdbrdcst_link join navaids_point.vor_p on service.infrmtnsrvctmslctp_nvdbrdcst_link.navaidbroadcast_hjid = navaids_point.vor_p.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_nvdbrdcst_link.informationservice_t_hjid ) as navaid_broadcast,
    -- composed AirspacePropertyType for client_airspace,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airspace.airspace_p.href,
    'nilreason', airspace.airspace_p.nil_reason,
    'title', airspace.airspace_p.simple_link_title)),'[]'::jsonb) from service.infrmtnsrvctmslctp_clntarspc_link join airspace.airspace_p on service.infrmtnsrvctmslctp_clntarspc_link.clientairspace_hjid = airspace.airspace_p.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_clntarspc_link.informationservice_t_hjid ) as client_airspace,
