select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeSegmentTerminationType for getendconditiondesignatoritem,
    procedure.missedapproachleg_t.endconditiondesignator::text,
    procedure.missedapproachleg_t.endconditiondesignatornilreason::text,
    -- embedded CodeTrajectoryType for getlegpathitem,
    procedure.missedapproachleg_t.legpath::text,
    procedure.missedapproachleg_t.legpathnilreason::text,
    -- embedded CodeSegmentPathType for getlegtypearincitem,
    procedure.missedapproachleg_t.legtypearinc::text,
    procedure.missedapproachleg_t.legtypearincnilreason::text,
    -- embedded ValBearingType for getcourseitem,
    procedure.missedapproachleg_t.course::text,
    procedure.missedapproachleg_t.coursenilreason::text,
    -- embedded CodeCourseType for getcoursetypeitem,
    procedure.missedapproachleg_t.coursetype::text,
    procedure.missedapproachleg_t.coursetypenilreason::text,
    -- embedded CodeDirectionReferenceType for getcoursedirectionitem,
    procedure.missedapproachleg_t.coursedirection::text,
    procedure.missedapproachleg_t.coursedirectionnilreason::text,
    -- embedded CodeDirectionTurnType for getturndirectionitem,
    procedure.missedapproachleg_t.turndirection::text,
    procedure.missedapproachleg_t.turndirectionnilreason::text,
    -- embedded CodeSpeedReferenceType for getspeedreferenceitem,
    procedure.missedapproachleg_t.speedreference::text,
    procedure.missedapproachleg_t.speedreferencenilreason::text,
    -- embedded CodeAltitudeUseType for getspeedinterpretationitem,
    procedure.missedapproachleg_t.speedinterpretation::text,
    procedure.missedapproachleg_t.speedinterpretationnilreason::text,
    -- embedded ValAngleType for getbankangleitem,
    procedure.missedapproachleg_t.bankangle::text,
    procedure.missedapproachleg_t.bankanglenilreason::text,
    -- embedded CodeYesNoType for getprocedureturnrequireditem,
    procedure.missedapproachleg_t.procedureturnrequired::text,
    procedure.missedapproachleg_t.procedureturnrequirednilreason::text,
    -- embedded CodeVerticalReferenceType for getupperlimitreferenceitem,
    procedure.missedapproachleg_t.upperlimitreference::text,
    procedure.missedapproachleg_t.upperlimitreferencenilreason::text,
    -- embedded CodeVerticalReferenceType for getlowerlimitreferenceitem,
    procedure.missedapproachleg_t.lowerlimitreference::text,
    procedure.missedapproachleg_t.lowerlimitreferencenilreason::text,
    -- embedded CodeAltitudeUseType for getaltitudeinterpretationitem,
    procedure.missedapproachleg_t.altitudeinterpretation::text,
    procedure.missedapproachleg_t.altitudeinterpretationnilreason::text,
    -- embedded CodeVerticalReferenceType for getaltitudeoverridereferenceitem,
    procedure.missedapproachleg_t.altitudeoverridereference::text,
    procedure.missedapproachleg_t.altitudeoverridereferencenilreason::text,
    -- embedded ValAngleType for getverticalangleitem,
    procedure.missedapproachleg_t.verticalangle::text,
    procedure.missedapproachleg_t.verticalanglenilreason::text,
    -- embedded CodeMissedApproachType for gettypeitem,
    procedure.missedapproachleg_t.type::text,
    procedure.missedapproachleg_t.typenilreason::text,
    -- embedded CodeYesNoType for getthresholdaftermaptitem,
    procedure.missedapproachleg_t.thresholdaftermapt::text,
    procedure.missedapproachleg_t.thresholdaftermaptnilreason::text,
    -- embedded CodeRNPType for getrequirednavigationperformanceitem,
    procedure.missedapproachleg_t.requirednavigationperformance::text,
    procedure.missedapproachleg_t.requirednavigationperformancenilreason::text,
    -- embedded ValSpeedType for getspeedlimititem,
    procedure.missedapproachleg_t.speedlimit::text,
    procedure.missedapproachleg_t.speedlimituom::text,
    procedure.missedapproachleg_t.speedlimitnilreason::text,
    -- embedded ValDistanceType for getlengthitem,
    procedure.missedapproachleg_t.length::text,
    procedure.missedapproachleg_t.lengthuom::text,
    procedure.missedapproachleg_t.lengthnilreason::text,
    -- embedded ValDurationType for getdurationitem,
    procedure.missedapproachleg_t.duration::text,
    procedure.missedapproachleg_t.durationuom::text,
    procedure.missedapproachleg_t.durationnilreason::text,
    -- embedded ValDistanceVerticalType for getupperlimitaltitudeitem,
    procedure.missedapproachleg_t.upperlimitaltitude::text,
    procedure.missedapproachleg_t.upperlimitaltitudeuom::text,
    procedure.missedapproachleg_t.upperlimitaltitudenilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlimitaltitudeitem,
    procedure.missedapproachleg_t.lowerlimitaltitude::text,
    procedure.missedapproachleg_t.lowerlimitaltitudeuom::text,
    procedure.missedapproachleg_t.lowerlimitaltitudenilreason::text,
    -- embedded ValDistanceVerticalType for getaltitudeoverrideatcitem,
    procedure.missedapproachleg_t.altitudeoverrideatc::text,
    procedure.missedapproachleg_t.altitudeoverrideatcuom::text,
    procedure.missedapproachleg_t.altitudeoverrideatcnilreason::text,
    -- embedded ValDistanceVerticalType for getheightmaptitem,
    procedure.missedapproachleg_t.heightmapt::text,
    procedure.missedapproachleg_t.heightmaptuom::text,
    procedure.missedapproachleg_t.heightmaptnilreason::text,
    -- composed geometry AIXMCurvePropertyType for trajectory,
    aixm_curve_pt_view_cjeivb.geom as trajectory_geom,
    jsonb_build_object('hjid', aixm_curve_pt_view_cjeivb.hjid,
    'id', aixm_curve_pt_view_cjeivb.id,
    'horizontalaccuracy', aixm_curve_pt_view_cjeivb.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_curve_pt_view_cjeivb.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_curve_pt_view_cjeivb.horizontalaccuracy_nilreason) AS trajectory,
    -- composed TerminalSegmentPointPropertyType for start_point,
    jsonb_build_object('hjid', aixm_property_xxlchk.hjid,
    'nilreason', aixm_property_xxlchk.nil_reason) AS start_point,
    -- composed TerminalSegmentPointPropertyType for end_point,
    jsonb_build_object('hjid', aixm_property_vtjhdy.hjid,
    'nilreason', aixm_property_vtjhdy.nil_reason) AS end_point,
    -- composed TerminalSegmentPointPropertyType for arc_centre,
    jsonb_build_object('hjid', aixm_property_zkybfr.hjid,
    'nilreason', aixm_property_zkybfr.nil_reason) AS arc_centre,
    -- composed AngleIndicationPropertyType for angle,
    jsonb_build_object('href', angleindication_traplr.href,
    'nilreason', angleindication_traplr.nil_reason,
    'title', angleindication_traplr.simple_link_title) AS angle,
    -- composed DistanceIndicationPropertyType for distance,
    jsonb_build_object('href', distanceindication_fjkpqw.href,
    'nilreason', distanceindication_fjkpqw.nil_reason,
    'title', distanceindication_fjkpqw.simple_link_title) AS distance,
    -- composed HoldingUsePropertyType for holding,
    jsonb_build_object('hjid', aixm_property_wuageq.hjid,
    'nilreason', aixm_property_wuageq.nil_reason) AS holding,
    -- composed InstrumentApproachProcedurePropertyType for approach,
    jsonb_build_object('href', instrumentapproachprocedure_ecwegd.href,
    'nilreason', instrumentapproachprocedure_ecwegd.nil_reason,
    'title', instrumentapproachprocedure_ecwegd.simple_link_title) AS approach,
    -- composed AircraftCharacteristicPropertyType for aircraft_category,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.mssdapprchlgtmslctp_arcrftctgr_link join aixm.aixm_property on procedure.mssdapprchlgtmslctp_arcrftctgr_link.aircraftcategory_hjid = aixm.aixm_property.hjid where procedure.missedapproachleg_t.hjid = procedure.mssdapprchlgtmslctp_arcrftctgr_link.missedapproachleg_t_hjid ) as aircraft_category,
    -- composed ObstacleAssessmentAreaPropertyType for design_surface,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.mssdapprchlgtmslctp_dsgnsrfc_link join aixm.aixm_property on procedure.mssdapprchlgtmslctp_dsgnsrfc_link.designsurface_hjid = aixm.aixm_property.hjid where procedure.missedapproachleg_t.hjid = procedure.mssdapprchlgtmslctp_dsgnsrfc_link.missedapproachleg_t_hjid ) as design_surface,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.mssdapprchlgtmslctp_annttn_link join aixm.aixm_property on procedure.mssdapprchlgtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.missedapproachleg_t.hjid = procedure.mssdapprchlgtmslctp_annttn_link.missedapproachleg_t_hjid ) as annotation,
    -- composed ApproachConditionPropertyType for condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.mssdapprchlgtmslctp_cndtn_link join aixm.aixm_property on procedure.mssdapprchlgtmslctp_cndtn_link.condition_hjid = aixm.aixm_property.hjid where procedure.missedapproachleg_t.hjid = procedure.mssdapprchlgtmslctp_cndtn_link.missedapproachleg_t_hjid ) as condition
from aixm.aixm_feature
inner join procedure.missedapproachleg_f on aixm.aixm_feature.hjid = procedure.missedapproachleg_f.hjid
inner join procedure.missedapproachleg_tp on aixm.aixm_feature.hjid = procedure.missedapproachleg_tp.timeslice_hjid
inner join procedure.missedapproachleg_t on procedure.missedapproachleg_tp.missedapproachlegtimeslice_hjid = procedure.missedapproachleg_t.hjid
inner join aixm.aixm_timeslice on procedure.missedapproachleg_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.mssdapprchlgtmslctp_strtpnt_link procedure_hqfbfd on procedure.missedapproachleg_t.hjid = procedure_hqfbfd.missedapproachleg_t_hjid
left join aixm.aixm_property aixm_property_xxlchk on procedure_hqfbfd.startpoint_hjid = aixm_property_xxlchk.hjid
-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.mssdapprchlgtmslctp_endpnt_link procedure_xmkxag on procedure.missedapproachleg_t.hjid = procedure_xmkxag.missedapproachleg_t_hjid
left join aixm.aixm_property aixm_property_vtjhdy on procedure_xmkxag.endpoint_hjid = aixm_property_vtjhdy.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.mssdapprchlgtmslctp_trjctr_link procedure_rnsikd on procedure.missedapproachleg_t.hjid = procedure_rnsikd.missedapproachleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_cjeivb on procedure_rnsikd.trajectory_hjid = aixm_curve_pt_view_cjeivb.hjid
-- composed TerminalSegmentPointPropertyType for arc_centre
left join procedure.mssdapprchlgtmslctp_arccntr_link procedure_trtitl on procedure.missedapproachleg_t.hjid = procedure_trtitl.missedapproachleg_t_hjid
left join aixm.aixm_property aixm_property_zkybfr on procedure_trtitl.arccentre_hjid = aixm_property_zkybfr.hjid
-- composed AngleIndicationPropertyType for angle
left join procedure.mssdapprchlgtmslctp_angl_link procedure_yvlydi on procedure.missedapproachleg_t.hjid = procedure_yvlydi.missedapproachleg_t_hjid
left join navaids_point.angleindication_p angleindication_traplr on procedure_yvlydi.angle_hjid = angleindication_traplr.hjid
-- composed DistanceIndicationPropertyType for distance
left join procedure.mssdapprchlgtmslctp_dstnc_link procedure_hoogox on procedure.missedapproachleg_t.hjid = procedure_hoogox.missedapproachleg_t_hjid
left join navaids_point.distanceindication_p distanceindication_fjkpqw on procedure_hoogox.distance_hjid = distanceindication_fjkpqw.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.mssdapprchlgtmslctp_hldng_link procedure_egxdbz on procedure.missedapproachleg_t.hjid = procedure_egxdbz.missedapproachleg_t_hjid
left join aixm.aixm_property aixm_property_wuageq on procedure_egxdbz.holding_hjid = aixm_property_wuageq.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.mssdapprchlgtmslctp_apprch_link procedure_xqcogs on procedure.missedapproachleg_t.hjid = procedure_xqcogs.missedapproachleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_ecwegd on procedure_xqcogs.approach_hjid = instrumentapproachprocedure_ecwegd.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists procedure_missedapproachleg_hjid on procedure.missedapproachleg_view (message_hjid, hjid, timeslice_hjid);
create index if not exists procedure_missedapproachleg_hjid on procedure.missedapproachleg_view (hjid);
create index if not exists procedure_missedapproachleg_trajectory_geom on procedure.missedapproachleg_view  using gist (trajectory_geom);

--navaids_point.navaid_view

drop materialized view if exists navaids_point.navaid_view cascade;
create materialized view navaids_point.navaid_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeNavaidServiceType for gettypeitem,
    navaids_point.navaid_t.type::text,
    navaids_point.navaid_t.typenilreason::text,
    -- embedded CodeNavaidDesignatorType for getdesignatoritem,
    navaids_point.navaid_t.designator::text,
    navaids_point.navaid_t.designatornilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    navaids_point.navaid_t.name::text,
    navaids_point.navaid_t.namenilreason::text,
    -- embedded CodeYesNoType for getflightcheckeditem,
    navaids_point.navaid_t.flightchecked::text,
    navaids_point.navaid_t.flightcheckednilreason::text,
    -- embedded CodeNavaidPurposeType for getpurposeitem,
    navaids_point.navaid_t.purpose::text,
    navaids_point.navaid_t.purposenilreason::text,
    -- embedded CodeSignalPerformanceILSType for getsignalperformanceitem,
    navaids_point.navaid_t.signalperformance::text,
    navaids_point.navaid_t.signalperformancenilreason::text,
    -- embedded CodeCourseQualityILSType for getcoursequalityitem,
    navaids_point.navaid_t.coursequality::text,
    navaids_point.navaid_t.coursequalitynilreason::text,
    -- embedded CodeIntegrityLevelILSType for getintegritylevelitem,
    navaids_point.navaid_t.integritylevel::text,
    navaids_point.navaid_t.integritylevelnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_ustule.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_ustule.hjid,
    'id', aixm_elevated_point_pt_view_ustule.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_ustule.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_ustule.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_ustule.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_ustule.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_ustule.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_ustule.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_ustule.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_ustule.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_ustule.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_ustule.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_ustule.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_ustule.elevation_nilreason) AS location,
    -- composed TouchDownLiftOffPropertyType for touch_down_lift_off,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.touchdownliftoff_p.href,
    'nilreason', airport_heliport.touchdownliftoff_p.nil_reason,
    'title', airport_heliport.touchdownliftoff_p.simple_link_title)),'[]'::jsonb) from navaids_point.nvdtmslctp_tchdwnlftoff_link join airport_heliport.touchdownliftoff_p on navaids_point.nvdtmslctp_tchdwnlftoff_link.touchdownliftoff_hjid = airport_heliport.touchdownliftoff_p.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_tchdwnlftoff_link.navaid_t_hjid ) as touch_down_lift_off,
    -- composed NavaidComponentPropertyType for navaid_equipment,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.nvdtmslctp_nvdeqpmnt_link join aixm.aixm_property on navaids_point.nvdtmslctp_nvdeqpmnt_link.navaidequipment_hjid = aixm.aixm_property.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_nvdeqpmnt_link.navaid_t_hjid ) as navaid_equipment,
    -- composed RunwayDirectionPropertyType for runway_direction,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.runwaydirection_p.href,
    'nilreason', airport_heliport.runwaydirection_p.nil_reason,
    'title', airport_heliport.runwaydirection_p.simple_link_title)),'[]'::jsonb) from navaids_point.nvdtmslctp_rnwdrctn_link join airport_heliport.runwaydirection_p on navaids_point.nvdtmslctp_rnwdrctn_link.runwaydirection_hjid = airport_heliport.runwaydirection_p.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_rnwdrctn_link.navaid_t_hjid ) as runway_direction,
    -- composed AirportHeliportPropertyType for served_airport,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.airportheliport_p.href,
    'nilreason', airport_heliport.airportheliport_p.nil_reason,
    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from navaids_point.nvdtmslctp_srvdarprt_link join airport_heliport.airportheliport_p on navaids_point.nvdtmslctp_srvdarprt_link.servedairport_hjid = airport_heliport.airportheliport_p.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_srvdarprt_link.navaid_t_hjid ) as served_airport,
    -- composed NavaidOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.nvdtmslctp_avlblt_link join aixm.aixm_property on navaids_point.nvdtmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_avlblt_link.navaid_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.nvdtmslctp_annttn_link join aixm.aixm_property on navaids_point.nvdtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_annttn_link.navaid_t_hjid ) as annotation
from aixm.aixm_feature
inner join navaids_point.navaid_f on aixm.aixm_feature.hjid = navaids_point.navaid_f.hjid
inner join navaids_point.navaid_tp on aixm.aixm_feature.hjid = navaids_point.navaid_tp.timeslice_hjid
