    jsonb_build_object('hjid', aixm_elevated_surface_pt_view_dtlxzj.hjid,
    'id', aixm_elevated_surface_pt_view_dtlxzj.id,
    'horizontalaccuracy', aixm_elevated_surface_pt_view_dtlxzj.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_surface_pt_view_dtlxzj.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_surface_pt_view_dtlxzj.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_surface_pt_view_dtlxzj.geoidundulation,
    'geoidundulation_uom', aixm_elevated_surface_pt_view_dtlxzj.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_surface_pt_view_dtlxzj.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_surface_pt_view_dtlxzj.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_surface_pt_view_dtlxzj.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_surface_pt_view_dtlxzj.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_surface_pt_view_dtlxzj.elevation,
    'elevation_uom', aixm_elevated_surface_pt_view_dtlxzj.elevation_uom,
    'elevation_nilreason', aixm_elevated_surface_pt_view_dtlxzj.elevation_nilreason) AS surface_extent,
    -- composed AirportHeliportPropertyType for associated_airport,
    jsonb_build_object('href', airportheliport_nwsihz.href,
    'nilreason', airportheliport_nwsihz.nil_reason,
    'title', airportheliport_nwsihz.simple_link_title) AS associated_airport,
    -- composed SurfaceCharacteristicsPropertyType for surface_properties,
    jsonb_build_object('hjid', aixm_property_ioxmdn.hjid,
    'nilreason', aixm_property_ioxmdn.nil_reason) AS surface_properties,
    -- composed AircraftStandPropertyType for accessible_stand,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.aircraftstand_p.href,
    'nilreason', airport_heliport.aircraftstand_p.nil_reason,
    'title', airport_heliport.aircraftstand_p.simple_link_title)),'[]'::jsonb) from airport_heliport.rdtmslctp_accssblstnd_link join airport_heliport.aircraftstand_p on airport_heliport.rdtmslctp_accssblstnd_link.accessiblestand_hjid = airport_heliport.aircraftstand_p.hjid where airport_heliport.road_t.hjid = airport_heliport.rdtmslctp_accssblstnd_link.road_t_hjid ) as accessible_stand,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.rdtmslctp_annttn_link join aixm.aixm_property on airport_heliport.rdtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.road_t.hjid = airport_heliport.rdtmslctp_annttn_link.road_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.road_f on aixm.aixm_feature.hjid = airport_heliport.road_f.hjid
inner join airport_heliport.road_tp on aixm.aixm_feature.hjid = airport_heliport.road_tp.timeslice_hjid
inner join airport_heliport.road_t on airport_heliport.road_tp.roadtimeslice_hjid = airport_heliport.road_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.road_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AirportHeliportPropertyType for associated_airport
left join airport_heliport.rdtmslctp_assctdarprt_link airport_heliport_qyzylu on airport_heliport.road_t.hjid = airport_heliport_qyzylu.road_t_hjid
left join airport_heliport.airportheliport_p airportheliport_nwsihz on airport_heliport_qyzylu.associatedairport_hjid = airportheliport_nwsihz.hjid
-- composed SurfaceCharacteristicsPropertyType for surface_properties
left join airport_heliport.rdtmslctp_srfcprprts_link airport_heliport_plzwng on airport_heliport.road_t.hjid = airport_heliport_plzwng.road_t_hjid
left join aixm.aixm_property aixm_property_ioxmdn on airport_heliport_plzwng.surfaceproperties_hjid = aixm_property_ioxmdn.hjid
-- composed AIXMElevatedSurfacePropertyType for surface_extent
left join airport_heliport.rdtmslctp_srfcextnt_link airport_heliport_qmwqez on airport_heliport.road_t.hjid = airport_heliport_qmwqez.road_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_dtlxzj on airport_heliport_qmwqez.surfaceextent_hjid = aixm_elevated_surface_pt_view_dtlxzj.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists airport_heliport_road_hjid on airport_heliport.road_view (message_hjid, hjid, timeslice_hjid);
create index if not exists airport_heliport_road_hjid on airport_heliport.road_view (hjid);
create index if not exists airport_heliport_road_surface_extent_geom on airport_heliport.road_view  using gist (surface_extent_geom);

--route.routedme_view

drop materialized view if exists route.routedme_view cascade;
create materialized view route.routedme_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeYesNoType for getcriticaldmeitem,
    route.routedme_t.criticaldme::text,
    route.routedme_t.criticaldmenilreason::text,
    -- embedded CodeYesNoType for getsatisfactoryitem,
    route.routedme_t.satisfactory::text,
    route.routedme_t.satisfactorynilreason::text,
    -- composed DMEPropertyType for referenced_dme,
    jsonb_build_object('href', dme_gehqrw.href,
    'nilreason', dme_gehqrw.nil_reason,
    'title', dme_gehqrw.simple_link_title) AS referenced_dme,
    -- composed RoutePortionPropertyType for applicable_route_portion,
    jsonb_build_object('hjid', aixm_property_aaucwe.hjid,
    'nilreason', aixm_property_aaucwe.nil_reason) AS applicable_route_portion,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtdmetmslctp_annttn_link join aixm.aixm_property on route.rtdmetmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.routedme_t.hjid = route.rtdmetmslctp_annttn_link.routedme_t_hjid ) as annotation
from aixm.aixm_feature
inner join route.routedme_f on aixm.aixm_feature.hjid = route.routedme_f.hjid
inner join route.routedme_tp on aixm.aixm_feature.hjid = route.routedme_tp.timeslice_hjid
inner join route.routedme_t on route.routedme_tp.routedmetimeslice_hjid = route.routedme_t.hjid
inner join aixm.aixm_timeslice on route.routedme_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed DMEPropertyType for referenced_dme
left join route.rtdmetmslctp_rfrncddme_link route_gxizzy on route.routedme_t.hjid = route_gxizzy.routedme_t_hjid
left join navaids_point.dme_p dme_gehqrw on route_gxizzy.referenceddme_hjid = dme_gehqrw.hjid
-- composed RoutePortionPropertyType for applicable_route_portion
left join route.rtdmetmslctp_applcblrtprtn_link route_pmwhoj on route.routedme_t.hjid = route_pmwhoj.routedme_t_hjid
left join aixm.aixm_property aixm_property_aaucwe on route_pmwhoj.applicablerouteportion_hjid = aixm_property_aaucwe.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists route_routedme_hjid on route.routedme_view (message_hjid, hjid, timeslice_hjid);
create index if not exists route_routedme_hjid on route.routedme_view (hjid);

