    route.routesegment_t.truetracknilreason::text,
    -- embedded ValBearingType for getmagnetictrackitem,
    route.routesegment_t.magnetictrack::text,
    route.routesegment_t.magnetictracknilreason::text,
    -- embedded ValBearingType for getreversetruetrackitem,
    route.routesegment_t.reversetruetrack::text,
    route.routesegment_t.reversetruetracknilreason::text,
    -- embedded ValBearingType for getreversemagnetictrackitem,
    route.routesegment_t.reversemagnetictrack::text,
    route.routesegment_t.reversemagnetictracknilreason::text,
    -- embedded CodeDirectionTurnType for getturndirectionitem,
    route.routesegment_t.turndirection::text,
    route.routesegment_t.turndirectionnilreason::text,
    -- embedded CodeYesNoType for getsignalgapitem,
    route.routesegment_t.signalgap::text,
    route.routesegment_t.signalgapnilreason::text,
    -- embedded CodeVerticalReferenceType for getminimumcrossingatendreferenceitem,
    route.routesegment_t.minimumcrossingatendreference::text,
    route.routesegment_t.minimumcrossingatendreferencenilreason::text,
    -- embedded CodeVerticalReferenceType for getmaximumcrossingatendreferenceitem,
    route.routesegment_t.maximumcrossingatendreference::text,
    route.routesegment_t.maximumcrossingatendreferencenilreason::text,
    -- embedded CodeRouteNavigationType for getnavigationtypeitem,
    route.routesegment_t.navigationtype::text,
    route.routesegment_t.navigationtypenilreason::text,
    -- embedded CodeRNPType for getrequirednavigationperformanceitem,
    route.routesegment_t.requirednavigationperformance::text,
    route.routesegment_t.requirednavigationperformancenilreason::text,
    -- embedded CodeRouteDesignatorSuffixType for getdesignatorsuffixitem,
    route.routesegment_t.designatorsuffix::text,
    route.routesegment_t.designatorsuffixnilreason::text,
    -- embedded ValDistanceVerticalType for getupperlimititem,
    route.routesegment_t.upperlimit::text,
    route.routesegment_t.upperlimituom::text,
    route.routesegment_t.upperlimitnilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlimititem,
    route.routesegment_t.lowerlimit::text,
    route.routesegment_t.lowerlimituom::text,
    route.routesegment_t.lowerlimitnilreason::text,
    -- embedded ValDistanceVerticalType for getminimumobstacleclearancealtitudeitem,
    route.routesegment_t.minimumobstacleclearancealtitude::text,
    route.routesegment_t.minimumobstacleclearancealtitudeuom::text,
    route.routesegment_t.minimumobstacleclearancealtitudenilreason::text,
    -- embedded ValDistanceType for getlengthitem,
    route.routesegment_t.length::text,
    route.routesegment_t.lengthuom::text,
    route.routesegment_t.lengthnilreason::text,
    -- embedded ValDistanceType for getwidthleftitem,
    route.routesegment_t.widthleft::text,
    route.routesegment_t.widthleftuom::text,
    route.routesegment_t.widthleftnilreason::text,
    -- embedded ValDistanceType for getwidthrightitem,
    route.routesegment_t.widthright::text,
    route.routesegment_t.widthrightuom::text,
    route.routesegment_t.widthrightnilreason::text,
    -- embedded ValDistanceVerticalType for getminimumenroutealtitudeitem,
    route.routesegment_t.minimumenroutealtitude::text,
    route.routesegment_t.minimumenroutealtitudeuom::text,
    route.routesegment_t.minimumenroutealtitudenilreason::text,
    -- embedded ValDistanceVerticalType for getminimumcrossingatenditem,
    route.routesegment_t.minimumcrossingatend::text,
    route.routesegment_t.minimumcrossingatenduom::text,
    route.routesegment_t.minimumcrossingatendnilreason::text,
    -- embedded ValDistanceVerticalType for getmaximumcrossingatenditem,
    route.routesegment_t.maximumcrossingatend::text,
    route.routesegment_t.maximumcrossingatenduom::text,
    route.routesegment_t.maximumcrossingatendnilreason::text,
    -- composed geometry AIXMCurvePropertyType for curve_extent,
    aixm_curve_pt_view_byawtt.geom as curve_extent_geom,
    jsonb_build_object('hjid', aixm_curve_pt_view_byawtt.hjid,
    'id', aixm_curve_pt_view_byawtt.id,
    'horizontalaccuracy', aixm_curve_pt_view_byawtt.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_curve_pt_view_byawtt.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_curve_pt_view_byawtt.horizontalaccuracy_nilreason) AS curve_extent,
    -- composed EnRouteSegmentPointPropertyType for start,
    jsonb_build_object('hjid', aixm_property_zwhjfg.hjid,
    'nilreason', aixm_property_zwhjfg.nil_reason) AS start,
    -- composed RoutePropertyType for route_formed,
    jsonb_build_object('href', route_zxpnaf.href,
    'nilreason', route_zxpnaf.nil_reason,
    'title', route_zxpnaf.simple_link_title) AS route_formed,
    -- composed ObstacleAssessmentAreaPropertyType for evaluation_area,
    jsonb_build_object('hjid', aixm_property_sudzus.hjid,
    'nilreason', aixm_property_sudzus.nil_reason) AS evaluation_area,
    -- composed EnRouteSegmentPointPropertyType for end,
    jsonb_build_object('hjid', aixm_property_tcreed.hjid,
    'nilreason', aixm_property_tcreed.nil_reason) AS end,
    -- composed RouteAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtsgmnttmslctp_avlblt_link join aixm.aixm_property on route.rtsgmnttmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where route.routesegment_t.hjid = route.rtsgmnttmslctp_avlblt_link.routesegment_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtsgmnttmslctp_annttn_link join aixm.aixm_property on route.rtsgmnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.routesegment_t.hjid = route.rtsgmnttmslctp_annttn_link.routesegment_t_hjid ) as annotation
from aixm.aixm_feature
inner join route.routesegment_f on aixm.aixm_feature.hjid = route.routesegment_f.hjid
inner join route.routesegment_tp on aixm.aixm_feature.hjid = route.routesegment_tp.timeslice_hjid
inner join route.routesegment_t on route.routesegment_tp.routesegmenttimeslice_hjid = route.routesegment_t.hjid
inner join aixm.aixm_timeslice on route.routesegment_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed EnRouteSegmentPointPropertyType for start
left join route.rtsgmnttmslctp_strt_link route_vhenbt on route.routesegment_t.hjid = route_vhenbt.routesegment_t_hjid
left join aixm.aixm_property aixm_property_zwhjfg on route_vhenbt.start_hjid = aixm_property_zwhjfg.hjid
-- composed RoutePropertyType for route_formed
left join route.rtsgmnttmslctp_rtfrmd_link route_ablgov on route.routesegment_t.hjid = route_ablgov.routesegment_t_hjid
left join route.route_p route_zxpnaf on route_ablgov.routeformed_hjid = route_zxpnaf.hjid
-- composed ObstacleAssessmentAreaPropertyType for evaluation_area
left join route.rtsgmnttmslctp_evltnar_link route_tneixz on route.routesegment_t.hjid = route_tneixz.routesegment_t_hjid
left join aixm.aixm_property aixm_property_sudzus on route_tneixz.evaluationarea_hjid = aixm_property_sudzus.hjid
-- composed AIXMCurvePropertyType for curve_extent
left join route.rtsgmnttmslctp_crvextnt_link route_ozhemc on route.routesegment_t.hjid = route_ozhemc.routesegment_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_byawtt on route_ozhemc.curveextent_hjid = aixm_curve_pt_view_byawtt.hjid
-- composed EnRouteSegmentPointPropertyType for end
left join route.rtsgmnttmslctp_end__link route_finstj on route.routesegment_t.hjid = route_finstj.routesegment_t_hjid
left join aixm.aixm_property aixm_property_tcreed on route_finstj.end__hjid = aixm_property_tcreed.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists route_routesegment_hjid on route.routesegment_view (message_hjid, hjid, timeslice_hjid);
create index if not exists route_routesegment_hjid on route.routesegment_view (hjid);
create index if not exists route_routesegment_curve_extent_geom on route.routesegment_view  using gist (curve_extent_geom);

--route.route_view

