left join organisation.organisationauthority_p organisationauthority_jefgvj on organisation_alnmct.ownerorganisation_hjid = organisationauthority_jefgvj.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
