--airport_heliport.workarea_view

drop materialized view if exists airport_heliport.workarea_view cascade;
create materialized view airport_heliport.workarea_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeWorkAreaType for gettypeitem,
    airport_heliport.workarea_t.type::text,
    airport_heliport.workarea_t.typenilreason::text,
    -- embedded DateType for getplannedoperationalitem,
    airport_heliport.workarea_t.plannedoperational::text,
    airport_heliport.workarea_t.plannedoperationalnilreason::text,
    -- composed geometry AIXMElevatedSurfacePropertyType for extent,
    aixm_elevated_surface_pt_view_ybflzs.geom as extent_geom,
    jsonb_build_object('hjid', aixm_elevated_surface_pt_view_ybflzs.hjid,
    'id', aixm_elevated_surface_pt_view_ybflzs.id,
    'horizontalaccuracy', aixm_elevated_surface_pt_view_ybflzs.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_surface_pt_view_ybflzs.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_surface_pt_view_ybflzs.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_surface_pt_view_ybflzs.geoidundulation,
    'geoidundulation_uom', aixm_elevated_surface_pt_view_ybflzs.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_surface_pt_view_ybflzs.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_surface_pt_view_ybflzs.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_surface_pt_view_ybflzs.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_surface_pt_view_ybflzs.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_surface_pt_view_ybflzs.elevation,
    'elevation_uom', aixm_elevated_surface_pt_view_ybflzs.elevation_uom,
    'elevation_nilreason', aixm_elevated_surface_pt_view_ybflzs.elevation_nilreason) AS extent,
    -- composed AirportHeliportPropertyType for associated_airport_heliport,
    jsonb_build_object('href', airportheliport_kstbrw.href,
    'nilreason', airportheliport_kstbrw.nil_reason,
    'title', airportheliport_kstbrw.simple_link_title) AS associated_airport_heliport,
    -- composed WorkareaActivityPropertyType for activation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wrkartmslctp_actvtn_link join aixm.aixm_property on airport_heliport.wrkartmslctp_actvtn_link.activation_hjid = aixm.aixm_property.hjid where airport_heliport.workarea_t.hjid = airport_heliport.wrkartmslctp_actvtn_link.workarea_t_hjid ) as activation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wrkartmslctp_annttn_link join aixm.aixm_property on airport_heliport.wrkartmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.workarea_t.hjid = airport_heliport.wrkartmslctp_annttn_link.workarea_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.workarea_f on aixm.aixm_feature.hjid = airport_heliport.workarea_f.hjid
inner join airport_heliport.workarea_tp on aixm.aixm_feature.hjid = airport_heliport.workarea_tp.timeslice_hjid
inner join airport_heliport.workarea_t on airport_heliport.workarea_tp.workareatimeslice_hjid = airport_heliport.workarea_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.workarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AirportHeliportPropertyType for associated_airport_heliport
left join airport_heliport.wrkartmslctp_assctdarprthlprt_link airport_heliport_hxthwl on airport_heliport.workarea_t.hjid = airport_heliport_hxthwl.workarea_t_hjid
left join airport_heliport.airportheliport_p airportheliport_kstbrw on airport_heliport_hxthwl.associatedairportheliport_hjid = airportheliport_kstbrw.hjid
-- composed AIXMElevatedSurfacePropertyType for extent
left join airport_heliport.wrkartmslctp_extnt_link airport_heliport_mbbvni on airport_heliport.workarea_t.hjid = airport_heliport_mbbvni.workarea_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_ybflzs on airport_heliport_mbbvni.extent_hjid = aixm_elevated_surface_pt_view_ybflzs.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;
create unique index if not exists airport_heliport_workarea_hjid on airport_heliport.workarea_view (message_hjid, hjid, timeslice_hjid);
create index if not exists airport_heliport_workarea_hjid on airport_heliport.workarea_view (hjid);
create index if not exists airport_heliport_workarea_extent_geom on airport_heliport.workarea_view  using gist (extent_geom);

--object

--aerial_refuelling.aerialrefuellinganchor_view

