create materialized view aerial_refuelling.aerialrefuellinganchor_view as
select
    aerial_refuelling.aerialrefuellinganchor_p.hjid as hjid,
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_object.id::text) row,
    aixm.aixm_property.nil_reason::text AS nilreason,
    aixm.aixm_object.id,
    aixm.aixm_object.hjid as object_hjid,
    -- embedded ValBearingType for getoutboundcourseitem,
    aerial_refuelling.aerialrefuellinganchor_o.outboundcourse::text,
    aerial_refuelling.aerialrefuellinganchor_o.outboundcoursenilreason::text,
    -- embedded CodeCourseType for getoutboundcoursetypeitem,
    aerial_refuelling.aerialrefuellinganchor_o.outboundcoursetype::text,
    aerial_refuelling.aerialrefuellinganchor_o.outboundcoursetypenilreason::text,
    -- embedded ValBearingType for getinboundcourseitem,
    aerial_refuelling.aerialrefuellinganchor_o.inboundcourse::text,
    aerial_refuelling.aerialrefuellinganchor_o.inboundcoursenilreason::text,
    -- embedded CodeDirectionTurnType for getturndirectionitem,
    aerial_refuelling.aerialrefuellinganchor_o.turndirection::text,
    aerial_refuelling.aerialrefuellinganchor_o.turndirectionnilreason::text,
    -- embedded CodeVerticalReferenceType for getrefuellingbaselevelreferenceitem,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevelreference::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevelreferencenilreason::text,
    -- embedded ValSpeedType for getspeedlimititem,
    aerial_refuelling.aerialrefuellinganchor_o.speedlimit::text,
    aerial_refuelling.aerialrefuellinganchor_o.speedlimituom::text,
    aerial_refuelling.aerialrefuellinganchor_o.speedlimitnilreason::text,
    -- embedded ValDistanceType for getlegseparationitem,
    aerial_refuelling.aerialrefuellinganchor_o.legseparation::text,
    aerial_refuelling.aerialrefuellinganchor_o.legseparationuom::text,
    aerial_refuelling.aerialrefuellinganchor_o.legseparationnilreason::text,
    -- embedded ValDistanceType for getleglengthitem,
    aerial_refuelling.aerialrefuellinganchor_o.leglength::text,
    aerial_refuelling.aerialrefuellinganchor_o.leglengthuom::text,
    aerial_refuelling.aerialrefuellinganchor_o.leglengthnilreason::text,
    -- embedded ValDistanceVerticalType for getrefuellingbaselevelitem,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevel::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaseleveluom::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevelnilreason::text,
    -- composed geometry AIXMSurfacePropertyType for extent,
    aixm_surface_pt_view_pktzsg.geom as extent_geom,
    jsonb_build_object('hjid', aixm_surface_pt_view_pktzsg.hjid,
    'id', aixm_surface_pt_view_pktzsg.id,
    'horizontalaccuracy', aixm_surface_pt_view_pktzsg.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_surface_pt_view_pktzsg.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_surface_pt_view_pktzsg.horizontalaccuracy_nilreason) AS extent,
    -- composed AirspaceLayerPropertyType for vertical_extent,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link.verticalextent_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link.aerialrefuellinganchor_o_hjid ) as vertical_extent,
    -- composed AerialRefuellingPointPropertyType for point,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_pnt_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_pnt_link.point_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_pnt_link.aerialrefuellinganchor_o_hjid ) as point,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_annttn_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_annttn_link.aerialrefuellinganchor_o_hjid ) as annotation
from aerial_refuelling.aerialrefuellinganchor_p 
inner join aixm.aixm_property on aerial_refuelling.aerialrefuellinganchor_p.hjid = aixm.aixm_property.hjid
inner join aerial_refuelling.aerialrefuellinganchor_o on aerial_refuelling.aerialrefuellinganchor_p.aerialrefuellinganchor_hjid = aerial_refuelling.aerialrefuellinganchor_o.hjid
inner join aixm.aixm_object on aerial_refuelling.aerialrefuellinganchor_o.hjid = aixm.aixm_object.hjid
-- composed AIXMSurfacePropertyType for extent
left join aerial_refuelling.arlrfllnganchrtp_extnt_link aerial_refuelling_pfaxjj on aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling_pfaxjj.aerialrefuellinganchor_o_hjid
left join gml.aixm_surface_pt_view aixm_surface_pt_view_pktzsg on aerial_refuelling_pfaxjj.extent_hjid = aixm_surface_pt_view_pktzsg.hjid
;
create unique index if not exists aerial_refuelling_aerialrefuellinganchor_hjid on aerial_refuelling.aerialrefuellinganchor_view (hjid);
create index if not exists aerial_refuelling_aerialrefuellinganchor_extent_geom on aerial_refuelling.aerialrefuellinganchor_view  using gist (extent_geom);

--aerial_refuelling.aerialrefuellingpoint_view

