    aerial_refuelling.aerialrefuellingpoint_o.radarguidancenilreason::text,
    -- embedded NoSequenceType for getsequenceitem,
    aerial_refuelling.aerialrefuellingpoint_o.sequence::text,
    aerial_refuelling.aerialrefuellingpoint_o.sequencenilreason::text,
    -- embedded CodeAerialRefuellingPointType for getusagetypeitem,
    aerial_refuelling.aerialrefuellingpoint_o.usagetype::text,
    aerial_refuelling.aerialrefuellingpoint_o.usagetypenilreason::text,
    -- composed geometry AIXMPointPropertyType for point_choice_position,
    aixm_point_pt_view_dpdqda.geom as point_choice_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_dpdqda.hjid,
    'id', aixm_point_pt_view_dpdqda.id,
    'horizontalaccuracy', aixm_point_pt_view_dpdqda.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_dpdqda.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_dpdqda.horizontalaccuracy_nilreason) AS point_choice_position,
    -- composed DesignatedPointPropertyType for point_choice_fix_designated_point,
    jsonb_build_object('href', designatedpoint_slzhcv.href,
    'nilreason', designatedpoint_slzhcv.nil_reason,
    'title', designatedpoint_slzhcv.simple_link_title) AS point_choice_fix_designated_point,
    -- composed NavaidPropertyType for point_choice_navaid_system,
    jsonb_build_object('href', navaid_betpjm.href,
    'nilreason', navaid_betpjm.nil_reason,
    'title', navaid_betpjm.simple_link_title) AS point_choice_navaid_system,
    -- composed RunwayCentrelinePointPropertyType for point_choice_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_jjjfgp.href,
    'nilreason', runwaycentrelinepoint_jjjfgp.nil_reason,
    'title', runwaycentrelinepoint_jjjfgp.simple_link_title) AS point_choice_runway_point,
    -- composed TouchDownLiftOffPropertyType for point_choice_aiming_point,
    jsonb_build_object('href', touchdownliftoff_nniroa.href,
    'nilreason', touchdownliftoff_nniroa.nil_reason,
    'title', touchdownliftoff_nniroa.simple_link_title) AS point_choice_aiming_point,
    -- composed AirportHeliportPropertyType for point_choice_airport_reference_point,
    jsonb_build_object('href', airportheliport_ejpbbm.href,
    'nilreason', airportheliport_ejpbbm.nil_reason,
    'title', airportheliport_ejpbbm.simple_link_title) AS point_choice_airport_reference_point,
    -- composed RadioFrequencyAreaPropertyType for extended_service_volume,
    jsonb_build_object('href', radiofrequencyarea_shoovz.href,
    'nilreason', radiofrequencyarea_shoovz.nil_reason,
    'title', radiofrequencyarea_shoovz.simple_link_title) AS extended_service_volume,
    -- composed PointReferencePropertyType for facility_makeup,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngpnttp_fcltmkp_link join aixm.aixm_property on aerial_refuelling.arlrfllngpnttp_fcltmkp_link.facilitymakeup_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling.arlrfllngpnttp_fcltmkp_link.aerialrefuellingpoint_o_hjid ) as facility_makeup,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllngpnttp_annttn_link join aixm.aixm_property on aerial_refuelling.arlrfllngpnttp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling.arlrfllngpnttp_annttn_link.aerialrefuellingpoint_o_hjid ) as annotation
from aerial_refuelling.aerialrefuellingpoint_p 
inner join aixm.aixm_property on aerial_refuelling.aerialrefuellingpoint_p.hjid = aixm.aixm_property.hjid
inner join aerial_refuelling.aerialrefuellingpoint_o on aerial_refuelling.aerialrefuellingpoint_p.aerialrefuellingpoint_hjid = aerial_refuelling.aerialrefuellingpoint_o.hjid
inner join aixm.aixm_object on aerial_refuelling.aerialrefuellingpoint_o.hjid = aixm.aixm_object.hjid
