left join aerial_refuelling.arlrfllngpnttp_pntchcfxdsgntdpnt_link aerial_refuelling_fdzama on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_fdzama.aerialrefuellingpoint_o_hjid
left join navaids_point.designatedpoint_p designatedpoint_slzhcv on aerial_refuelling_fdzama.pointchoicefixdesignatedpoint_hjid = designatedpoint_slzhcv.hjid
-- composed NavaidPropertyType for point_choice_navaid_system
left join aerial_refuelling.arlrfllngpnttp_pntchcnvdsstm_link aerial_refuelling_avpgsa on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_avpgsa.aerialrefuellingpoint_o_hjid
left join navaids_point.navaid_p navaid_betpjm on aerial_refuelling_avpgsa.pointchoicenavaidsystem_hjid = navaid_betpjm.hjid
-- composed AIXMPointPropertyType for point_choice_position
left join aerial_refuelling.arlrfllngpnttp_pntchcpstn_link aerial_refuelling_xbedpm on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_xbedpm.aerialrefuellingpoint_o_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_dpdqda on aerial_refuelling_xbedpm.pointchoiceposition_hjid = aixm_point_pt_view_dpdqda.hjid
-- composed RunwayCentrelinePointPropertyType for point_choice_runway_point
left join aerial_refuelling.arlrfllngpnttp_pntchcrnwpnt_link aerial_refuelling_gicyuy on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_gicyuy.aerialrefuellingpoint_o_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_jjjfgp on aerial_refuelling_gicyuy.pointchoicerunwaypoint_hjid = runwaycentrelinepoint_jjjfgp.hjid
-- composed TouchDownLiftOffPropertyType for point_choice_aiming_point
left join aerial_refuelling.arlrfllngpnttp_pntchcamngpnt_link aerial_refuelling_ornlfy on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_ornlfy.aerialrefuellingpoint_o_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_nniroa on aerial_refuelling_ornlfy.pointchoiceaimingpoint_hjid = touchdownliftoff_nniroa.hjid
-- composed AirportHeliportPropertyType for point_choice_airport_reference_point
left join aerial_refuelling.arlrfllngpnttp_pntchcarprtrfrncpnt_link aerial_refuelling_rivefe on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_rivefe.aerialrefuellingpoint_o_hjid
left join airport_heliport.airportheliport_p airportheliport_ejpbbm on aerial_refuelling_rivefe.pointchoiceairportreferencepoint_hjid = airportheliport_ejpbbm.hjid
-- composed RadioFrequencyAreaPropertyType for extended_service_volume
left join aerial_refuelling.arlrfllngpnttp_extnddsrvcvlm_link aerial_refuelling_ounbhc on aerial_refuelling.aerialrefuellingpoint_o.hjid = aerial_refuelling_ounbhc.aerialrefuellingpoint_o_hjid
left join shared.radiofrequencyarea_p radiofrequencyarea_shoovz on aerial_refuelling_ounbhc.extendedservicevolume_hjid = radiofrequencyarea_shoovz.hjid
;
create unique index if not exists aerial_refuelling_aerialrefuellingpoint_hjid on aerial_refuelling.aerialrefuellingpoint_view (hjid);
create index if not exists aerial_refuelling_aerialrefuellingpoint_point_choice_position_geom on aerial_refuelling.aerialrefuellingpoint_view  using gist (point_choice_position_geom);

--aerial_refuelling.aerialrefuellingtrack_view

drop materialized view if exists aerial_refuelling.aerialrefuellingtrack_view cascade;
create materialized view aerial_refuelling.aerialrefuellingtrack_view as
select
    aerial_refuelling.aerialrefuellingtrack_p.hjid as hjid,
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_object.id::text) row,
    aixm.aixm_property.nil_reason::text AS nilreason,
