--route.flightrestrictionlevel_view

drop materialized view if exists route.flightrestrictionlevel_view cascade;
create materialized view route.flightrestrictionlevel_view as
select
    route.flightrestrictionlevel_p.hjid as hjid,
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_object.id::text) row,
    aixm.aixm_property.nil_reason::text AS nilreason,
    aixm.aixm_object.id,
    aixm.aixm_object.hjid as object_hjid,
    -- embedded CodeVerticalReferenceType for getupperlevelreferenceitem,
    route.flightrestrictionlevel_o.upperlevelreference::text,
    route.flightrestrictionlevel_o.upperlevelreferencenilreason::text,
    -- embedded CodeVerticalReferenceType for getlowerlevelreferenceitem,
    route.flightrestrictionlevel_o.lowerlevelreference::text,
    route.flightrestrictionlevel_o.lowerlevelreferencenilreason::text,
    -- embedded ValDistanceVerticalType for getupperlevelitem,
    route.flightrestrictionlevel_o.upperlevel::text,
    route.flightrestrictionlevel_o.upperleveluom::text,
    route.flightrestrictionlevel_o.upperlevelnilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlevelitem,
    route.flightrestrictionlevel_o.lowerlevel::text,
    route.flightrestrictionlevel_o.lowerleveluom::text,
    route.flightrestrictionlevel_o.lowerlevelnilreason::text,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.flghtrstrctnlvltp_annttn_link join aixm.aixm_property on route.flghtrstrctnlvltp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.flightrestrictionlevel_o.hjid = route.flghtrstrctnlvltp_annttn_link.flightrestrictionlevel_o_hjid ) as annotation
from route.flightrestrictionlevel_p 
inner join aixm.aixm_property on route.flightrestrictionlevel_p.hjid = aixm.aixm_property.hjid
inner join route.flightrestrictionlevel_o on route.flightrestrictionlevel_p.flightrestrictionlevel_hjid = route.flightrestrictionlevel_o.hjid
inner join aixm.aixm_object on route.flightrestrictionlevel_o.hjid = aixm.aixm_object.hjid
;
create unique index if not exists route_flightrestrictionlevel_hjid on route.flightrestrictionlevel_view (hjid);

